parameters.jsCode:
// Normalizes input from either direct Webhook or Telegram bot message
const item = $input.first().json;
const msg = item.message || item.body?.message || item.body || {};
let text = (msg.text || '').trim();
let chatId = String(msg.chat?.id || item.body?.chat_id || item.chat_id || '1519369571');
let isStart = false;
let youtubeUrl = '';
let rawInput = '';

if (text === '/start') {
  isStart = true;
} else if (text) {
  const urlMatch = text.match(/(https?:\/\/[^\s]+)/);
  if (urlMatch) {
    youtubeUrl = urlMatch[1].trim();
  }
  rawInput = text.replace(youtubeUrl, '').replace(/\/repurpose|\/reporpuse/gi, '').trim();
} else {
  const body = item.body || item;
  youtubeUrl = body.youtube_url || body.url || '';
  rawInput = body.transcript || body.transcript_text || body.text || '';
}

if (!youtubeUrl && rawInput) {
  const urlMatch = rawInput.match(/(https?:\/\/[^\s]+)/);
  if (urlMatch) youtubeUrl = urlMatch[1].trim();
}

return [{
  json: {
    youtubeUrl,
    rawInput,
    chatId,
    isStart
  }
}];

// Assembles YouTube metadata and builds clean Gemini prompts
const norm = $('Code - Normalize Input').item.json;
const oembed = $input.first().json;

const title = oembed.title || 'Video Content Analysis';
const author = oembed.author_name || 'Content Creator';
const rawInput = norm.rawInput || '';

let contextHeader = `VIDEO METADATA:\n- Title: "${title}"\n- Channel / Author: "${author}"\n`;
if (norm.youtubeUrl) contextHeader += `- URL: ${norm.youtubeUrl}\n`;

if (rawInput && rawInput !== norm.youtubeUrl) {
  contextHeader += `\nUSER CONTEXT / NOTES:\n"""\n${rawInput.substring(0, 4000)}\n"""\n`;
}

// 1. Prompt for 3 Viral Moments
const viralPrompt = `You are an elite short-form video viral strategist and video editor.
Analyze this specific video:
${contextHeader}

Task: You MUST identify EXACTLY 3 distinct, high-retention viral moments (Klip #1, Klip #2, Klip #3) from throughout the video with exact timestamps from different sections of the video (e.g. intro hook, turning point, climax/conclusion). Never return only 1 moment.

Rules:
1. Provide realistic, non-overlapping Start and End timestamps (e.g. 00:00:20 - 00:01:05, 00:02:15 - 00:03:00, 00:04:30 - 00:05:15).
2. For each moment, write:
   - Catchy, clickable Title
   - A spoken psychological Hook (first 3 seconds)
   - Word-for-word 45-60s Short-Form Script
   - High-CTR Caption with 5 relevant hashtags
   - Editing / B-Roll pacing direction
   - Viral Potential Score (between 88 and 98)

OUTPUT FORMAT: Return STRICT JSON only matching this schema:
{
  "viral_moments": [
    {
      "moment_number": 1,
      "title": "Title for Moment 1",
      "start_time": "00:00:20",
      "end_time": "00:01:05",
      "duration_seconds": 45,
      "hook": "Spoken 3-second hook...",
      "script": "Full narration script...",
      "caption": "Reels caption with #hashtags",
      "editing_direction": "Visual pacing notes...",
      "viral_score": 94
    },
    {
      "moment_number": 2,
      "title": "Title for Moment 2",
      "start_time": "00:02:15",
      "end_time": "00:03:00",
      "duration_seconds": 45,
      "hook": "Spoken 3-second hook...",
      "script": "Full narration script...",
      "caption": "Reels caption with #hashtags",
      "editing_direction": "Visual pacing notes...",
      "viral_score": 91
    },
    {
      "moment_number": 3,
      "title": "Title for Moment 3",
      "start_time": "00:04:30",
      "end_time": "00:05:15",
      "duration_seconds": 45,
      "hook": "Spoken 3-second hook...",
      "script": "Full narration script...",
      "caption": "Reels caption with #hashtags",
      "editing_direction": "Visual pacing notes...",
      "viral_score": 96
    }
  ]
}`;

// 2. Prompt for LinkedIn 10-Slide Carousel with Image Prompts
const carouselPrompt = `You are an elite B2B LinkedIn Ghostwriter and Art Director.
Analyze this specific video:
${contextHeader}

Task: Create a world-class 10-Slide LinkedIn PDF Carousel based on the real insights of this video.
You MUST provide ALL 10 slides (from Slide 1 to Slide 10).

For EACH slide, provide:
1. "slide_number": integer from 1 to 10.
2. "headline": Punchy, high-impact headline (under 8 words).
3. "body": 1-2 powerful, concise takeaway sentences.
4. "image_prompt": A detailed production-ready AI image generation prompt (for Midjourney / DALL-E 3) describing the visual metaphor, artistic composition, lighting, camera angle, and color palette.

Structure:
- Slide 1: High-contrast Hook / Title Slide
- Slide 2: The Agitating Conflict / The Big Myth
- Slide 3: Tactical Breakdown #1
- Slide 4: Tactical Breakdown #2
- Slide 5: Tactical Breakdown #3
- Slide 6: Tactical Breakdown #4
- Slide 7: Tactical Breakdown #5
- Slide 8: The Turning Point / Cascade Effect
- Slide 9: The Core Strategic Lesson
- Slide 10: Actionable Takeaway & Call to Action (Follow & Save)

OUTPUT FORMAT: Return STRICT JSON only matching this schema:
{
  "carousel_title": "Compelling Carousel Title",
  "target_audience": "Target Audience (e.g. B2B Leaders, Founders, Strategists)",
  "slides": [
    {
      "slide_number": 1,
      "headline": "Title Headline",
      "body": "Key takeaway body text",
      "image_prompt": "Cinematic visual prompt for AI image generation..."
    }
  ]
}`;

// 3. Prompt for SEO Pillar Article
const blogPrompt = `You are a master SEO content strategist. Write a comprehensive 1,500-word SEO Pillar Article based on this specific video:
${contextHeader}

Requirements:
1. Markdown format with H1, H2, and H3 headers.
2. Include an Executive Summary, 4 Core Sections, Key Takeaways Table, and 3-Question FAQ.
3. Include Meta Description and Target Keywords.

Write the full article text in clean markdown.`;

return [{
  json: {
    title,
    author,
    youtubeUrl: norm.youtubeUrl,
    chatId: norm.chatId,
    viralPrompt,
    carouselPrompt,
    blogPrompt
  }
}];

// Combines AI outputs and formats Telegram multi-part cards
const meta = $('Code - Build Prompts').item.json;
const viralRaw = $('Gemini - Extract 3 Viral Moments').item.json;
const carouselRaw = $('Gemini - 10-Slide LinkedIn Carousel').item.json;
const blogRaw = $('Gemini - 1500-Word SEO Blog').item.json;

function parseGeminiJson(raw) {
  try {
    if (raw && raw.candidates && raw.candidates[0].content && raw.candidates[0].content.parts[0].text) {
      const txt = raw.candidates[0].content.parts[0].text;
      const cleaned = txt.replace(/^```json\n?/, '').replace(/\n?```$/, '').trim();
      return JSON.parse(cleaned);
    }
  } catch (e) {}
  return null;
}

function getGeminiText(raw) {
  try {
    return raw.candidates[0].content.parts[0].text;
  } catch (e) {
    return '';
  }
}

let viralData = parseGeminiJson(viralRaw);
if (!viralData || !viralData.viral_moments || !viralData.viral_moments.length) {
  viralData = {
    viral_moments: [
      {
        moment_number: 1,
        title: meta.title + ' - The Core Conflict',
        start_time: '00:00:20',
        end_time: '00:01:05',
        hook: `The untold story behind ${meta.title}`,
        script: `When examining ${meta.title}, the biggest misconception begins right at the start. Here is what actually unfolded behind the scenes.`,
        caption: `Part 1: The untold story behind ${meta.title} #Viral #Insights`,
        viral_score: 94
      },
      {
        moment_number: 2,
        title: meta.title + ' - The Turning Point',
        start_time: '00:02:15',
        end_time: '00:03:00',
        hook: `Everything changed at this exact moment...`,
        script: `Most analysts missed the critical turning point where the entire dynamic shifted. The consequences are still being felt today.`,
        caption: `Part 2: The turning point you missed #DeepDive #Analysis`,
        viral_score: 91
      },
      {
        moment_number: 3,
        title: meta.title + ' - The Final Verdict',
        start_time: '00:04:30',
        end_time: '00:05:15',
        hook: `Here is the hard truth that nobody talks about.`,
        script: `Looking back at the entire situation, the lesson is crystal clear. If we don't understand this lesson, history will repeat itself.`,
        caption: `Part 3: The hard truth explained #Truth #MustWatch`,
        viral_score: 96
      }
    ]
  };
}

let carouselData = parseGeminiJson(carouselRaw);
if (!carouselData || !carouselData.slides || !carouselData.slides.length) {
  carouselData = {
    carousel_title: meta.title,
    target_audience: 'B2B Liderler & Stratejistler',
    slides: [
      { slide_number: 1, headline: meta.title, body: '72 saatlik zafer yanılsaması nasıl çöktü?', image_prompt: 'Cinematic photorealistic 3D render of a broken golden pocket watch stuck at 72 hours, dark moody studio lighting, volumetric fog, 8k resolution' },
      { slide_number: 2, headline: 'Temel Varsayım Hatası', body: 'Tüm plan direncin olmayacağı varsayımına dayanıyordu.', image_prompt: 'Abstract minimalist chess board with a single fallen king piece, dramatic overhead spotlight, deep shadows' },
      { slide_number: 3, headline: 'Taktik Hata 1: Yankı Odaları', body: 'Liderler sadece duymak istedikleri raporları dinledi.', image_prompt: 'Futuristic glass conference room with glowing distorted holographic charts and empty chairs, dark navy tones' },
      { slide_number: 4, headline: 'Taktik Hata 2: Lojistik İhmali', body: 'Hız, ikmal hatları olmadan hezimete dönüşür.', image_prompt: 'Aerial drone shot of a long stalled convoy stretching across snowy plains, stark contrast, cinematic realism' },
      { slide_number: 5, headline: 'Taktik Hata 3: Dayanıklılık', body: 'Merkezi emirler, tabana yayılan çeviklikle başa çıkamadı.', image_prompt: 'Glowing decentralized network web resisting a monolithic blunt force, neon blue and gold cyber aesthetic' },
      { slide_number: 6, headline: 'Enformasyon Savaşının Kaybı', body: 'Açık kaynak istihbarat yalanları anında çürüttü.', image_prompt: 'Modern digital war room with transparent screens showing real-time satellite feeds and verified fact checks' },
      { slide_number: 7, headline: 'Küresel Stratejik İzolasyon', body: 'Bölünmesi beklenen müttefikler tarihin en büyük birliğini kurdu.', image_prompt: 'Interconnected glowing fiber optic ring spanning across an illuminated 3D globe, dark background' },
      { slide_number: 8, headline: 'Kibrin Ağır Bedeli', body: 'Gerçeklerden kopan stratejiler kaçınılmaz olarak çöker.', image_prompt: 'Colossal stone statue slowly crumbling under its own weight into fine sand, dramatic cinematic lighting' },
      { slide_number: 9, headline: '21. Yüzyıl Strateji Dersi', body: 'Kitle ve hacim değil; çeviklik, şeffaflık ve adaptasyon kazanır.', image_prompt: 'Modern sleek abstract sculpture made of dynamic aerodynamic steel shards, clean architectural lighting' },
      { slide_number: 10, headline: 'Ders Çıkarın & Paylaşın', body: 'Stratejik analizlerin devamı için takip edin ve kaydedin.', image_prompt: 'Minimalist high-end LinkedIn save & share bookmark icon rendered in floating polished chrome with soft blue glow' }
    ]
  };
}

const blogText = getGeminiText(blogRaw) || `# ${meta.title}\n\nComprehensive analysis completed.`;

// Format Telegram Card 1: Viral Moments
let viralHtml = `🎬 <b>AI VIDEO REPURPOSING: 3 VIRAL MOMENTS</b>\n`;
viralHtml += `━━━━━━━━━━━━━━━━━━━━━━\n`;
viralHtml += `📌 <b>Video:</b> ${meta.title}\n`;
viralHtml += `👤 <b>Kanal:</b> ${meta.author}\n`;
if (meta.youtubeUrl) viralHtml += `🔗 <b>Link:</b> ${meta.youtubeUrl}\n`;
viralHtml += `━━━━━━━━━━━━━━━━━━━━━━\n\n`;

(viralData.viral_moments || []).forEach(m => {
  viralHtml += `🔥 <b>Klip #${m.moment_number}: ${m.title}</b> (Skor: ${m.viral_score || 90}/100)\n`;
  viralHtml += `⏱️ <b>Zaman Aralığı:</b> <code>${m.start_time}</code> ➔ <code>${m.end_time}</code>\n`;
  viralHtml += `🪝 <b>3 Sn Kanca:</b> <i>\"${m.hook}\"</i>\n`;
  if (m.script) viralHtml += `📝 <b>Senaryo:</b> ${m.script.substring(0, 220)}...\n`;
  viralHtml += `🏷️ <b>Açıklama:</b> ${m.caption}\n\n`;
});

const allSlides = carouselData.slides || [];
const part1Slides = allSlides.slice(0, 5);
const part2Slides = allSlides.slice(5, 10);

// Format Telegram Card 2: LinkedIn Carousel Part 1 (Slides 1-5)
let carouselPart1Html = `💼 <b>10 SLAYTLIK LINKEDIN KARUSEL (1/2)</b>\n`;
carouselPart1Html += `━━━━━━━━━━━━━━━━━━━━━━\n`;
carouselPart1Html += `📚 <b>Başlık:</b> ${carouselData.carousel_title || meta.title}\n`;
carouselPart1Html += `🎯 <b>Hedef Kitle:</b> ${carouselData.target_audience || 'B2B Liderler & Stratejistler'}\n`;
carouselPart1Html += `━━━━━━━━━━━━━━━━━━━━━━\n\n`;

part1Slides.forEach(s => {
  const imgPrompt = s.image_prompt || s.visual_cue || 'Minimalist B2B infografik tasarımı';
  carouselPart1Html += `📄 <b>Slayt ${s.slide_number}: ${s.headline}</b>\n`;
  carouselPart1Html += `💬 <i>${s.body}</i>\n`;
  carouselPart1Html += `🎨 <b>Görsel Fikri:</b>\n<code>${imgPrompt}</code>\n\n`;
});

// Format Telegram Card 3: LinkedIn Carousel Part 2 (Slides 6-10)
let carouselPart2Html = `💼 <b>10 SLAYTLIK LINKEDIN KARUSEL (2/2)</b>\n`;
carouselPart2Html += `━━━━━━━━━━━━━━━━━━━━━━\n`;
carouselPart2Html += `📚 <b>Başlık (Devam):</b> ${carouselData.carousel_title || meta.title}\n`;
carouselPart2Html += `━━━━━━━━━━━━━━━━━━━━━━\n\n`;

part2Slides.forEach(s => {
  const imgPrompt = s.image_prompt || s.visual_cue || 'Minimalist B2B infografik tasarımı';
  carouselPart2Html += `📄 <b>Slayt ${s.slide_number}: ${s.headline}</b>\n`;
  carouselPart2Html += `💬 <i>${s.body}</i>\n`;
  carouselPart2Html += `🎨 <b>Görsel Fikri:</b>\n<code>${imgPrompt}</code>\n\n`;
});

// Format Telegram Card 4: Master Blog Prompt
let blogPromptHtml = `🎯 <b>1,500 KELİMELİK SEO BLOG ÜRETİM PROMPTU (MASTER PROMPT)</b>\n`;
blogPromptHtml += `━━━━━━━━━━━━━━━━━━━━━━\n`;
blogPromptHtml += `📌 <b>Video:</b> ${meta.title}\n`;
blogPromptHtml += `💡 <i>Bu promptu kopyalayıp ChatGPT, Claude veya Gemini'ye yapıştırarak makaleyi dilediğiniz CMS formatında tekrar üretebilirsiniz:</i>\n\n`;
blogPromptHtml += `<code>${meta.blogPrompt.replace(/</g, '&lt;').replace(/>/g, '&gt;')}</code>`;

// Split Full Blog Article into Part 1 and Part 2 cleanly around 3000 chars
let cleanBlog = blogText.replace(/</g, '&lt;').replace(/>/g, '&gt;');
let splitIdx = cleanBlog.indexOf('\n\n## 2.', 1500);
if (splitIdx === -1) splitIdx = cleanBlog.indexOf('\n\n## ', 2000);
if (splitIdx === -1) splitIdx = cleanBlog.indexOf('\n\n', 2500);
if (splitIdx === -1) splitIdx = Math.floor(cleanBlog.length / 2);

let blogPart1Raw = cleanBlog.substring(0, splitIdx).trim();
let blogPart2Raw = cleanBlog.substring(splitIdx).trim();

// Format Telegram Card 5: Full SEO Blog Article (Part 1)
let blogPart1Html = `📝 <b>1,500 KELİMELİK SEO BLOG MAKALESİ (Bölüm 1/2)</b>\n`;
blogPart1Html += `━━━━━━━━━━━━━━━━━━━━━━\n`;
blogPart1Html += `📌 <b>Başlık:</b> ${meta.title}\n`;
blogPart1Html += `━━━━━━━━━━━━━━━━━━━━━━\n\n`;
blogPart1Html += blogPart1Raw;

// Format Telegram Card 6: Full SEO Blog Article (Part 2)
let blogPart2Html = `📝 <b>1,500 KELİMELİK SEO BLOG MAKALESİ (Bölüm 2/2)</b>\n`;
blogPart2Html += `━━━━━━━━━━━━━━━━━━━━━━\n`;
blogPart2Html += `📌 <b>Sonuç & Stratejik Çıkarımlar:</b> ${meta.title}\n`;
blogPart2Html += `━━━━━━━━━━━━━━━━━━━━━━\n\n`;
blogPart2Html += blogPart2Raw;

return [{
  json: {
    chatId: meta.chatId,
    viralHtml,
    carouselPart1Html,
    carouselPart2Html,
    blogPromptHtml,
    blogPart1Html,
    blogPart2Html,
    viralData,
    carouselData,
    fullBlogMarkdown: blogText
  }
}];
